# Bash completion for guardbee. Generated by scripts/gen-completions.sh from
# BINARY_NAME — do not hand-edit the command name here, re-run the generator.
_guardbee_complete() {
    local cur prev subcommands common_flags
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    subcommands="policies flows blame verdict ui version compat"
    common_flags="--kubeconfig --namespace -n --all-namespaces -A"
    # Flow filters (flowFilter in flows.go), shared by flows, blame and verdict.
    filter_flags="--pod --from-pod --from-label --from-ip --to-pod --to-service --to-label --to-ip --to-port --verdict --drop-reason-desc --type"

    if [[ "$COMP_CWORD" -eq 1 ]]; then
        COMPREPLY=($(compgen -W "$subcommands" -- "$cur"))
        return
    fi

    case "${COMP_WORDS[1]}" in
        policies)
            COMPREPLY=($(compgen -W "$common_flags" -- "$cur"))
            ;;
        flows)
            COMPREPLY=($(compgen -W "$common_flags $filter_flags --last --follow -f" -- "$cur"))
            ;;
        blame)
            COMPREPLY=($(compgen -W "$common_flags $filter_flags --last --follow -f --format" -- "$cur"))
            ;;
        verdict)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=($(compgen -W "$common_flags $filter_flags --last --follow -f --show-unchanged" -- "$cur"))
            else
                COMPREPLY=($(compgen -f -- "$cur"))
            fi
            ;;
        ui)
            COMPREPLY=($(compgen -W "--kubeconfig --addr --enable-probes --probe-image" -- "$cur"))
            ;;
        version)
            COMPREPLY=($(compgen -W "--kubeconfig --client" -- "$cur"))
            ;;
    esac
}
complete -F _guardbee_complete guardbee
